import { resolvePlugins } from './resolve.js';
import type { LectioPlugin } from './types.js';

export interface GeneratePluginModuleOptions {
  /**
   * Where the generated module imports `createPluginRuntime` from.
   * Defaults to `'@eventuras/lectio-docs/plugins/runtime'`.
   */
  runtimeModule?: string;
}

/**
 * Source of a module that exports the configured plugins as a ready
 * `PluginRuntime`, for hosts with a bundler. Write it next to the app, and
 * import `plugins` from it:
 *
 * ```ts
 * // Generated by lectio — do not edit.
 * import { createPluginRuntime } from '@eventuras/lectio-docs/plugins/runtime';
 *
 * export const plugins = createPluginRuntime([
 *   {
 *     name: "mermaid",
 *     fences: ["mermaid"],
 *     options: {"theme":"neutral"},
 *     load: () => import("@eventuras/lectio-plugin-mermaid/client"),
 *   },
 * ]);
 * ```
 *
 * Each client module sits behind a dynamic `import()` with a literal
 * specifier, so a bundler can find it and split it into its own chunk. It
 * loads the first time a page renders one of its fences, never during a
 * server render. The output is valid as both JavaScript and TypeScript.
 *
 * The plugins are validated with {@link resolvePlugins} first, so a bad config
 * fails here rather than in the browser.
 */
export function generatePluginModule(
  plugins: readonly LectioPlugin[] | undefined,
  options: GeneratePluginModuleOptions = {},
): string {
  const runtimeModule = options.runtimeModule ?? '@eventuras/lectio-docs/plugins/runtime';

  // Every value goes in through JSON.stringify, which also makes it a safe JS
  // literal: a module name can't break out of its string.
  const entries = resolvePlugins(plugins).map((plugin) => {
    const lines = [`    name: ${JSON.stringify(plugin.name)},`, `    fences: ${JSON.stringify(plugin.fences)},`];
    if (plugin.client) {
      lines.push(`    options: ${JSON.stringify(plugin.client.options)},`);
      lines.push(`    load: () => import(${JSON.stringify(plugin.client.module)}),`);
    }
    return `  {\n${lines.join('\n')}\n  },`;
  });

  const list = entries.length > 0 ? `[\n${entries.join('\n')}\n]` : '[]';

  return [
    '// Generated by lectio — do not edit.',
    `import { createPluginRuntime } from ${JSON.stringify(runtimeModule)};`,
    '',
    `export const plugins = createPluginRuntime(${list});`,
    '',
  ].join('\n');
}
